package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen0Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale result = LocaleUtils.toLocale("en");
        assertEquals("en", result.getLanguage());
        assertEquals("", result.getCountry());
    }

    @Test
    public void testToLocale_ValidLanguageAndCountry() {
        Locale result = LocaleUtils.toLocale("en_US");
        assertEquals("en", result.getLanguage());
        assertEquals("US", result.getCountry());
    }

    @Test
    public void testToLocale_ValidLanguageCountryVariant() {
        Locale result = LocaleUtils.toLocale("en_US_POSIX");
        assertEquals("en", result.getLanguage());
        assertEquals("US", result.getCountry());
        assertEquals("POSIX", result.getVariant());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength_TooShort() {
        LocaleUtils.toLocale("e");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength_TooLongButNotSpecific() {
        // Length 6 is not 2, 5, or < 7 is false, but logic checks len != 2 && len != 5 && len < 7
        // If len is 6: (6!=2 is T) && (6!=5 is T) && (6<7 is T) -> throws
        LocaleUtils.toLocale("en_US_");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLanguageChars_Uppercase() {
        LocaleUtils.toLocale("EN");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLanguageChars_Symbols() {
        LocaleUtils.toLocale("e1");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidCountrySeparator() {
        // len is 5, but charAt(2) must be '_'
        LocaleUtils.toLocale("en-US");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidCountryChars_Lowercase() {
        LocaleUtils.toLocale("en_us");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidCountryChars_Symbols() {
        LocaleUtils.toLocale("en_U!");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidVariantSeparator() {
        // len is 7, but charAt(5) must be '_'
        // "en_USX" -> len 6, fails first check.
        // "en_US_A" -> len 7. charAt(5) is '_'
        // Let's try "en_US-A" -> len 7. charAt(5) is '-'
        LocaleUtils.toLocale("en_US-A");
    }

    @Test(expected = IllegalArgumentException.class)
    public void testToLocale_InvalidLength_EdgeCase() {
        // len 3: (3!=2 is T) && (3!=5 is T) && (3<7 is T) -> throws
        LocaleUtils.toLocale("en_");
    }
}
